DROP PROCEDURE IF EXISTS `SP_ACTUALIZAR_CONSOLIDADO_INVERSIONES`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_ACTUALIZAR_CONSOLIDADO_INVERSIONES` ()   BEGIN


/*
 CREATE TABLE `consolidado_inversiones` (
  `fechaExpiracion` date NOT NULL,
  `empresa` varchar(60) NOT NULL,
  `propietario` varchar(60) NOT NULL,
  `tasa` decimal(8,2) DEFAULT NULL,
  `rendimiento` decimal(8,2) DEFAULT NULL,
  `capital` decimal(8,2) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
*/
  
  truncate TABLE consolidado_inversiones;
  
  where  
  am_fecha_pago > NOW()
  and inv_emisor not like '%BONOS%'
       and A.is_active = 1
       and A.is_deleted = 0
	   and I.is_deleted = 0
       and A.inv_id = I.id  
  group by empresa, fechaExpiracion, inv_propietario
  order by fechaExpiracion ;
  
select  fechaVencimiento, codigoBCE, propietario, tasaMensualReal, rendimiento, valorConComision from bonos 
  where  
  fechaVencimiento > NOW()
       and is_active = 1
       and is_deleted = 0  
  order by fechaVencimiento ;


SELECT 
    *
FROM
    consolidado_inversiones 
UNION SELECT 
    'X' AS fechaExpiracion,
    '' AS empresa,
    'TOTAL' AS propietario,
    '' AS tasa,
    '' AS rendimiento,
    SUM(capital) AS capital
FROM
    consolidado_inversiones;



END$$

DROP PROCEDURE IF EXISTS `SP_ACTUALIZAR_RESUMEN_QUINCENAL`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_ACTUALIZAR_RESUMEN_QUINCENAL` ()   BEGIN

SET @NUM_DIAS = 15;

truncate table rendimientos_his;

SELECT 
     5,
    `EMISOR`,
    AVG(`PRECIO_PORC`),
    AVG(`RENDIMIENTO`),
    AVG(`PLAZO_DIAS`),
    AVG(`INTERES`),
    SUM(VALOR_NOMINAL),
    SUM(VALOR_EFECTIVO),
    `EMISION`,
    `VENCIMIENTO`,
    `TIPO_MERCADO`,
    count(*) AS contador
FROM `obligaciones_his`
WHERE `FECHA` BETWEEN DATE_SUB(CURRENT_DATE, INTERVAL @NUM_DIAS DAY) AND CURRENT_DATE
GROUP BY `EMISOR`,`EMISION`, `VENCIMIENTO`, `TIPO_MERCADO`
ORDER BY RENDIMIENTO DESC;

SELECT 
     3,
    `EMISOR`,
    AVG(`PRECIO_PORC`),
    AVG(`RENDIMIENTO`),
    AVG(`PLAZO_DIAS`),
    AVG(`RENDIMIENTO`),
    SUM(VALOR_NOMINAL),
    SUM(VALOR_EFECTIVO),
    `EMISION`,
    `VENCIMIENTO`,
    `MERCADO`,
    count(*) AS contador
FROM `papeles_his`
WHERE `FECHA` BETWEEN DATE_SUB(CURRENT_DATE, INTERVAL @NUM_DIAS DAY) AND CURRENT_DATE
GROUP BY `EMISOR`,`EMISION`, `VENCIMIENTO`, `MERCADO`
ORDER BY RENDIMIENTO DESC;

SELECT 
     2,
    `EMISOR`,
    AVG(`PRECIO_PORC`),
    AVG(`RENDIMIENTO`),
    datediff(VENCIMIENTO, EMISION),
    AVG(`RENDIMIENTO`),
	SUM(VALOR_NOMINAL),
    SUM(VALOR_EFECTIVO),
    `EMISION`,
    `VENCIMIENTO`,
    '',
    count(*) AS contador
FROM `facturas_his`
WHERE `FECHA` BETWEEN DATE_SUB(CURRENT_DATE, INTERVAL @NUM_DIAS DAY) AND CURRENT_DATE
GROUP BY `EMISOR`,`EMISION`, `VENCIMIENTO`
ORDER BY RENDIMIENTO DESC;



SELECT 
     74,
    `EMISOR`,
    AVG(`PRECIO_PORC`),
    AVG(`RENDIMIENTO`),
    AVG(`PLAZO_DIAS`),
    AVG(`INTERES`),
	SUM(VALOR_NOMINAL),
    SUM(VALOR_EFECTIVO),
    `EMISION`,
    `VENCIMIENTO`,
    `MERCADO`,
    count(*) AS contador
FROM genericos_his
WHERE `FECHA` BETWEEN DATE_SUB(CURRENT_DATE, INTERVAL @NUM_DIAS DAY) AND CURRENT_DATE
GROUP BY `EMISOR`,`EMISION`, `VENCIMIENTO`, `MERCADO`
ORDER BY RENDIMIENTO DESC;

SELECT 
     75,
    `EMISOR`,
    AVG(`PRECIO_PORC`),
    AVG(`RENDIMIENTO`),
    AVG(`PLAZO_DIAS`),
    AVG(`INTERES`),
	SUM(VALOR_NOMINAL),
    SUM(VALOR_EFECTIVO),
    `EMISION`,
    `VENCIMIENTO`,
    `MERCADO`,
    count(*) AS contador
FROM titularizaciones_his
WHERE `FECHA` BETWEEN DATE_SUB(CURRENT_DATE, INTERVAL @NUM_DIAS DAY) AND CURRENT_DATE
GROUP BY `EMISOR`,`EMISION`, `VENCIMIENTO`, `MERCADO`
ORDER BY RENDIMIENTO DESC;


SELECT 
    D.DIC_VALUE,
    R.`EMISOR`,
    R.`PRECIO_PORC`,
    R.`RENDIMIENTO`,
    R.`PLAZO_DIAS`,
    R.`INTERES`,
    R.`VALOR_NOMINAL`,
    R.`VALOR_EFECTIVO`,
    R.`EMISION`,
    R.`VENCIMIENTO`,
    R.`TIPO_MERCADO`,
    R.CONTADOR
FROM `rendimientos_his` R, DICTIONARY D
    WHERE R.`TIPO` = D.DIC_ID
    order by rendimiento desc, interes desc, plazo_dias asc LIMIT 30;

END$$

DROP PROCEDURE IF EXISTS `SP_ACTUALIZAR_SHARES_LAST_DATE`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_ACTUALIZAR_SHARES_LAST_DATE` ()   BEGIN
        TRUNCATE TABLE shares_lastdate;

        DROP TEMPORARY TABLE IF EXISTS temp_top2_fechas;
        CREATE TEMPORARY TABLE temp_top2_fechas AS
        SELECT sha_issuer_id, sha_issuer, sha_date, orden
        FROM (
            SELECT 
                SHA_ISSUER_ID as sha_issuer_id,
                SHA_ISSUER as sha_issuer,
                SHA_DATE as sha_date,
                ROW_NUMBER() OVER (PARTITION BY SHA_ISSUER_ID ORDER BY SHA_DATE DESC) as orden
            FROM shares
            WHERE SHA_CASH_VALUE > 0 
              AND SHA_DATE <= CURRENT_DATE()
            GROUP BY SHA_ISSUER_ID, SHA_ISSUER, SHA_DATE
        ) t
        WHERE orden <= 2;

            SHA_ISSUER_ID,
            SHA_ISSUER,
            MAX_DATE,
            AVG_PRICE,
            MIN_PRICE,
            MAX_PRICE,
            PREV_DATE,
            PREV_AVG_PRICE,
            PREV_MIN_PRICE,
            PREV_MAX_PRICE,
            DAILY_CHANGE,
            DAILY_VARIATION_PCT
        )
        SELECT 
            u.sha_issuer_id,
            u.sha_issuer,
            u.max_date,
            u.avg_price,
            u.min_price,
            u.max_price,
            p.prev_date,
            p.prev_avg_price,
            p.prev_min_price,
            p.prev_max_price,
            ROUND(u.avg_price - COALESCE(p.prev_avg_price, u.avg_price), 2) AS DAILY_CHANGE,
            CASE 
                WHEN COALESCE(p.prev_avg_price, 0) > 0 
                THEN ROUND(((u.avg_price - p.prev_avg_price) / p.prev_avg_price) * 100, 2)
                ELSE 0.00
            END AS DAILY_VARIATION_PCT
        FROM (
            SELECT 
                s.SHA_ISSUER_ID as sha_issuer_id,
                s.SHA_ISSUER as sha_issuer,
                tf.sha_date as max_date,
                ROUND(SUM(s.SHA_CASH_VALUE) / SUM(s.SHA_NUMBER), 2) as avg_price,
                ROUND(MIN(s.SHA_PRICE), 2) as min_price,
                ROUND(MAX(s.SHA_PRICE), 2) as max_price
            FROM shares s
            INNER JOIN temp_top2_fechas tf ON s.SHA_ISSUER_ID = tf.sha_issuer_id AND s.SHA_DATE = tf.sha_date
            WHERE tf.orden = 1
            GROUP BY s.SHA_ISSUER_ID, s.SHA_ISSUER, tf.sha_date
        ) u
        LEFT JOIN (
            SELECT 
                s.SHA_ISSUER_ID as sha_issuer_id,
                tf.sha_date as prev_date,
                ROUND(SUM(s.SHA_CASH_VALUE) / SUM(s.SHA_NUMBER), 2) as prev_avg_price,
                ROUND(MIN(s.SHA_PRICE), 2) as prev_min_price,
                ROUND(MAX(s.SHA_PRICE), 2) as prev_max_price
            FROM shares s
            INNER JOIN temp_top2_fechas tf ON s.SHA_ISSUER_ID = tf.sha_issuer_id AND s.SHA_DATE = tf.sha_date
            WHERE tf.orden = 2
            GROUP BY s.SHA_ISSUER_ID, tf.sha_date
        ) p ON u.sha_issuer_id = p.sha_issuer_id;

        DROP TEMPORARY TABLE IF EXISTS temp_top2_fechas;
    END$$

DROP PROCEDURE IF EXISTS `SP_AMORTIZATION_BY_ENTERPRISE`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_AMORTIZATION_BY_ENTERPRISE` ()   BEGIN
  
SELECT LEFT(inv_emisor, LENGTH(inv_emisor) - 10) AS empresa,
       SUM(am_capital) AS capital
 FROM amortizacion A, inversion I
WHERE DATE(am_fecha_pago) > CURDATE()  -- Condición para incluir registros del día de hoy
  AND inv_emisor NOT LIKE '%BONOS%'
  AND A.is_active = 1
       and A.is_deleted = 0
       and I.is_deleted = 0
       and A.inv_id = I.id
GROUP BY empresa
ORDER BY capital DESC;
  
END$$

DROP PROCEDURE IF EXISTS `SP_AMORTIZATION_BY_ENTERPRISE_OLD`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_AMORTIZATION_BY_ENTERPRISE_OLD` ()   BEGIN

  select am_enterprise as empresa, sum(am_principal) as capital from amortization 
  where  
  am_expiration_date > NOW()
  and am_enterprise not like '%BONOS%'
  group by am_enterprise;
  
  
  
END$$

DROP PROCEDURE IF EXISTS `SP_AMORTIZATION_BY_MONTH_OWNER`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_AMORTIZATION_BY_MONTH_OWNER` (IN `_year` INT, IN `_month` INT)   BEGIN
    SELECT
        am_fecha_pago AS fecha, 
        inv_propietario AS propietario,
        LEFT(inv_emisor, LENGTH(inv_emisor) - 10) AS empresa,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_interes ELSE 0 END) AS interes,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_capital ELSE 0 END) AS capital,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_descuento ELSE 0 END) AS descuento,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_interes ELSE 0 END) AS interes_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_capital ELSE 0 END) AS capital_moroso,
        SUM(CASE WHEN A.am_pagada = 2 THEN am_descuento ELSE 0 END) AS descuento_moroso,
        SUM(am_interes + am_capital) AS total
    FROM amortizacion A, inversion I
    WHERE (am_fecha_pago AND MONTH(am_fecha_pago) = _month AND YEAR(am_fecha_pago) = _year)
       -- OR (_month = 0 AND YEAR(am_fecha_pago) = _year)
       -- and is_active = 1
       -- and inv_fecha_venta is null
       -- and A.is_active = 1
       and (A.is_active = 1 OR  I.inv_fecha_venta IS NULL)
       and A.is_deleted = 0
	   and I.is_deleted = 0
       and A.inv_id = I.id
	GROUP by fecha, propietario, empresa
    
            UNION
    SELECT
        "X" AS fecha,
        "" AS propietario,
        "TOTAL" AS empresa,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_interes ELSE 0 END) AS interes,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_capital ELSE 0 END) AS capital,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_descuento ELSE 0 END) AS descuento,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_interes ELSE 0 END) AS interes_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_capital ELSE 0 END) AS capital_moroso,
        SUM(CASE WHEN A.am_pagada = 2 THEN am_descuento ELSE 0 END) AS descuento_moroso,
        SUM(am_interes) + SUM(am_capital) AS total
    FROM amortizacion A, inversion I
    WHERE (am_fecha_pago AND MONTH(am_fecha_pago) = _month AND YEAR(am_fecha_pago) = _year)
       -- OR (_month = 0 AND YEAR(am_fecha_pago) = _year)
       -- and is_active = 1
	   -- and A.is_active = 1
       and (A.is_active = 1 OR  I.inv_fecha_venta IS NULL)
       -- and inv_fecha_venta is null
       and A.is_deleted = 0
	   and I.is_deleted = 0
       and A.inv_id = I.id 
    
    ORDER BY FECHA, PROPIETARIO;


END$$

DROP PROCEDURE IF EXISTS `SP_AMORTIZATION_BY_OWNER`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_AMORTIZATION_BY_OWNER` ()   BEGIN

select inv_propietario, sum(am_capital) from amortizacion A, inversion I 
  where  
  am_fecha_pago > NOW()
  and inv_emisor not like '%BONOS%'
  and A.is_active = 1
  and A.is_deleted = 0
  and I.is_deleted = 0
  and A.inv_id = I.id
  group by inv_propietario;
  
  

END$$

DROP PROCEDURE IF EXISTS `SP_AMORTIZATION_DETAIL_BY_DATES`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_AMORTIZATION_DETAIL_BY_DATES` (IN `_initialDate` DATE, IN `_finalDate` DATE)   BEGIN
    SELECT
        inv_fecha_compra AS compra,
        am_fecha_pago AS fecha, 
        inv_propietario AS propietario,
        inv_emisor AS empresa,
        inv_tasa_interes AS tasa,
        inv_rendimiento_nominal AS rendimiento,
        (CASE WHEN A.am_pagada IN (1,0) THEN am_interes ELSE 0 END) AS interes,
		(CASE WHEN A.am_pagada IN (1,0) THEN am_capital ELSE 0 END) AS capital,
        (CASE WHEN A.am_pagada IN (1,0) THEN am_descuento ELSE 0 END) AS descuento,
		(CASE WHEN A.am_pagada = 2 THEN am_interes ELSE 0 END) AS interes_moroso,
		(CASE WHEN A.am_pagada = 2 THEN am_capital ELSE 0 END) AS capital_moroso,
        (CASE WHEN A.am_pagada = 2 THEN am_descuento ELSE 0 END) AS descuento_moroso,
        am_interes + am_capital AS total
     FROM amortizacion A, inversion I 
    WHERE (am_fecha_pago between _initialDate and _finalDate)
--       and is_active = 1
       -- and inv_fecha_venta is null
       and A.is_active = 1
       and A.is_deleted = 0
	   and I.is_deleted = 0
       and A.inv_id = I.id
        UNION
    SELECT
        "" AS compra,
        "X" AS fecha,
        "" AS propietario,
        "TOTAL" AS empresa,
        "" AS tasa,        
        "" AS rendimiento,                
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_interes ELSE 0 END) AS interes,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_capital ELSE 0 END) AS capital,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_descuento ELSE 0 END) AS descuento,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_interes ELSE 0 END) AS interes_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_capital ELSE 0 END) AS capital_moroso,
        SUM(CASE WHEN A.am_pagada = 2 THEN am_descuento ELSE 0 END) AS descuento_moroso,
        SUM(am_interes) + SUM(am_capital) AS total
    FROM amortizacion A, inversion I 
		 WHERE (am_fecha_pago between _initialDate and _finalDate)
  --       and is_active = 1
       --  and inv_fecha_venta is null
       and A.is_active = 1
       and A.is_deleted = 0
	   and I.is_deleted = 0
       and A.inv_id = I.id
       
	ORDER BY FECHA, PROPIETARIO;
    
    
END$$

DROP PROCEDURE IF EXISTS `SP_AMORTIZATION_DETAIL_BY_MONTH`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_AMORTIZATION_DETAIL_BY_MONTH` (IN `_year` INT, IN `_month` INT)   BEGIN
    SELECT
