       and A.is_deleted = 0
	   and I.is_deleted = 0
       and A.inv_id = I.id
    
        UNION
    SELECT
        "" AS compra,
        "X" AS fecha,
        "" AS propietario,
        "TOTAL" AS empresa,
        "" AS tasa,        
        "" AS rendimiento,                
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_interes ELSE 0 END) AS interes,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_capital ELSE 0 END) AS capital,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_descuento ELSE 0 END) AS descuento,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_interes ELSE 0 END) AS interes_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_capital ELSE 0 END) AS capital_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_descuento ELSE 0 END) AS descuento_moroso,
        SUM(am_interes) + SUM(am_capital) AS total
    FROM amortizacion A, inversion I
    WHERE (am_fecha_pago AND MONTH(am_fecha_pago) = _month AND YEAR(am_fecha_pago) = _year)
       -- OR (_month = 0 AND YEAR(am_fecha_pago) = _year)
      -- and is_active = 1
      -- and inv_fecha_venta is null
	   -- and A.is_active = 1
       and (A.is_active = 1 OR  I.inv_fecha_venta IS NULL)
       and A.is_deleted = 0
	   and I.is_deleted = 0
       and A.inv_id = I.id
	ORDER BY FECHA, PROPIETARIO, COMPRA;
    
    
END$$

DROP PROCEDURE IF EXISTS `SP_AMORTIZATION_SUMMARY`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_AMORTIZATION_SUMMARY` (IN `OPC` INT)   BEGIN
    SELECT
        YEAR(am_fecha_pago) AS anio,
        CASE
            WHEN MONTH(am_fecha_pago) = 1 THEN 'Enero'
            WHEN MONTH(am_fecha_pago) = 2 THEN 'Febrero'
            WHEN MONTH(am_fecha_pago) = 3 THEN 'Marzo'
            WHEN MONTH(am_fecha_pago) = 4 THEN 'Abril'
            WHEN MONTH(am_fecha_pago) = 5 THEN 'Mayo'
            WHEN MONTH(am_fecha_pago) = 6 THEN 'Junio'
            WHEN MONTH(am_fecha_pago) = 7 THEN 'Julio'
            WHEN MONTH(am_fecha_pago) = 8 THEN 'Agosto'
            WHEN MONTH(am_fecha_pago) = 9 THEN 'Septiembre'
            WHEN MONTH(am_fecha_pago) = 10 THEN 'Octubre'
            WHEN MONTH(am_fecha_pago) = 11 THEN 'Noviembre'
            WHEN MONTH(am_fecha_pago) = 12 THEN 'Diciembre'
        END AS mes,
        SUM(am_interes) AS interes,
        SUM(am_capital) AS capital,
        SUM(am_interes) + SUM(am_capital) AS total
    FROM amortizacion
    WHERE am_fecha_pago
       -- and is_active = 1
       and is_deleted = 0  
       and inv_fecha_venta is null
    GROUP BY YEAR(am_fecha_pago), MONTH(am_fecha_pago)
    ORDER BY am_fecha_pago;    


END$$

DROP PROCEDURE IF EXISTS `SP_AMORTIZATION_SUMMARY_BY_DATES`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_AMORTIZATION_SUMMARY_BY_DATES` (IN `_initialDate` DATE, IN `_finalDate` DATE)   BEGIN
    SELECT
        am_fecha_pago AS fecha, 
        inv_propietario AS propietario,
        LEFT(inv_emisor, LENGTH(inv_emisor) - 10) AS empresa,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_interes ELSE 0 END) AS interes,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_capital ELSE 0 END) AS capital,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_descuento ELSE 0 END) AS descuento,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_interes ELSE 0 END) AS interes_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_capital ELSE 0 END) AS capital_moroso,
        SUM(CASE WHEN A.am_pagada = 2 THEN am_descuento ELSE 0 END) AS descuento_moroso,
        sum(am_interes + am_capital) AS total
    FROM amortizacion A, inversion I
    WHERE am_fecha_pago between _initialDate and _finalDate
       -- and is_active = 1
       -- and inv_fecha_venta is null
       and A.is_active = 1
       and A.is_deleted = 0
	   and I.is_deleted = 0
       and A.inv_id = I.id
	GROUP by fecha, propietario, empresa
    
            UNION
    SELECT
        "X" AS fecha,
        "" AS propietario,
        "TOTAL" AS empresa,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_interes ELSE 0 END) AS interes,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_capital ELSE 0 END) AS capital,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_descuento ELSE 0 END) AS descuento,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_interes ELSE 0 END) AS interes_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_capital ELSE 0 END) AS capital_moroso,
        SUM(CASE WHEN A.am_pagada = 2 THEN am_descuento ELSE 0 END) AS descuento_moroso,
        SUM(am_interes) + SUM(am_capital) AS total
    FROM amortizacion A, inversion I
    WHERE am_fecha_pago between _initialDate and _finalDate
       -- and is_active = 1
       and A.is_active = 1
       and A.is_deleted = 0
	   and I.is_deleted = 0
       and A.inv_id = I.id
       -- and inv_fecha_venta is null    
    ORDER BY FECHA, PROPIETARIO;


END$$

DROP PROCEDURE IF EXISTS `SP_AMORTIZATION_SUMMARY_BY_MONTH`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_AMORTIZATION_SUMMARY_BY_MONTH` (IN `OPC` INT, IN `_year` INT, IN `_month` INT)   BEGIN
    SELECT
        YEAR(am_fecha_pago) AS anio,
        CASE
            WHEN MONTH(am_fecha_pago) = 1 THEN 'Enero'
            WHEN MONTH(am_fecha_pago) = 2 THEN 'Febrero'
            WHEN MONTH(am_fecha_pago) = 3 THEN 'Marzo'
            WHEN MONTH(am_fecha_pago) = 4 THEN 'Abril'
            WHEN MONTH(am_fecha_pago) = 5 THEN 'Mayo'
            WHEN MONTH(am_fecha_pago) = 6 THEN 'Junio'
            WHEN MONTH(am_fecha_pago) = 7 THEN 'Julio'
            WHEN MONTH(am_fecha_pago) = 8 THEN 'Agosto'
            WHEN MONTH(am_fecha_pago) = 9 THEN 'Septiembre'
            WHEN MONTH(am_fecha_pago) = 10 THEN 'Octubre'
            WHEN MONTH(am_fecha_pago) = 11 THEN 'Noviembre'
            WHEN MONTH(am_fecha_pago) = 12 THEN 'Diciembre'
        END AS mes,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_interes ELSE 0 END) AS interes,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_capital ELSE 0 END) AS capital,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_descuento ELSE 0 END) AS descuento,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_interes ELSE 0 END) AS interes_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_capital ELSE 0 END) AS capital_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_descuento ELSE 0 END) AS descuento_moroso,
        SUM(am_interes) + SUM(am_capital) AS total
    FROM amortizacion A, inversion I
    WHERE (am_fecha_pago AND MONTH(am_fecha_pago) = _month AND YEAR(am_fecha_pago) = _year)
       OR (_month = 0 AND YEAR(am_fecha_pago) = _year)
      -- and is_active = 1
	   -- and A.is_active = 1
       and (A.is_active = 1 OR  I.inv_fecha_venta IS NULL)
       and A.is_deleted = 0
       and I.is_deleted = 0
       and A.inv_id = I.id
       -- and inv_fecha_venta is null
    GROUP BY YEAR(am_fecha_pago), MONTH(am_fecha_pago)
	UNION
    SELECT
        _year AS anio,
        'ANUAL TOTAL' AS mes,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_interes ELSE 0 END) AS interes,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_capital ELSE 0 END) AS capital,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_descuento ELSE 0 END) AS descuento,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_interes ELSE 0 END) AS interes_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_capital ELSE 0 END) AS capital_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_descuento ELSE 0 END) AS descuento_moroso,
        SUM(am_interes) + SUM(am_capital) AS total
    FROM amortizacion A, inversion I
    WHERE (am_fecha_pago AND YEAR(am_fecha_pago) = _year)
       -- and is_active = 1
	   -- and A.is_active = 1
       and (A.is_active = 1 OR  I.inv_fecha_venta IS NULL)
       and A.is_deleted = 0
       and I.is_deleted = 0
       and A.inv_id = I.id
       -- and inv_fecha_venta is null
    UNION
    SELECT
        _year AS anio,
        'ANUAL EJECUTADO' AS mes,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_interes ELSE 0 END) AS interes,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_capital ELSE 0 END) AS capital,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_descuento ELSE 0 END) AS descuento,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_interes ELSE 0 END) AS interes_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_capital ELSE 0 END) AS capital_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_descuento ELSE 0 END) AS descuento_moroso,
        SUM(am_interes) + SUM(am_capital) AS total
    FROM amortizacion A, inversion I
    WHERE (am_fecha_pago AND YEAR(am_fecha_pago) = _year)
       -- and is_active = 1
	   and A.is_active = 1
       and A.is_deleted = 0
       and I.is_deleted = 0
       and A.inv_id = I.id
       and am_fecha_pago <= curdate()
       -- and inv_fecha_venta is null
    UNION
    SELECT
        _year AS anio,
        'ANUAL PENDIENTE' AS mes,
        SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_interes ELSE 0 END) AS interes,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_capital ELSE 0 END) AS capital,
		SUM(CASE WHEN A.am_pagada IN (1,0) THEN am_descuento ELSE 0 END) AS descuento,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_interes ELSE 0 END) AS interes_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_capital ELSE 0 END) AS capital_moroso,
		SUM(CASE WHEN A.am_pagada = 2 THEN am_descuento ELSE 0 END) AS descuento_moroso,
        SUM(am_interes) + SUM(am_capital) AS total
    FROM amortizacion A, inversion I
    WHERE (am_fecha_pago AND YEAR(am_fecha_pago) = _year)
       -- and is_active = 1
	   -- and A.is_active = 1
       and (A.is_active = 1 OR  I.inv_fecha_venta IS NULL)
       and A.is_deleted = 0
       and I.is_deleted = 0
       and A.inv_id = I.id
       and am_fecha_pago > curdate() 
       -- and inv_fecha_venta is null
       ;

END$$

DROP PROCEDURE IF EXISTS `SP_BALANCE`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_BALANCE` (IN `initial_date` VARCHAR(10), IN `final_date` VARCHAR(10))   BEGIN

/*
    DECLARE initial_date DATE;
    DECLARE final_date DATE;
  delete from balance;
  
  
  	SET @fecha1 = SUBSTRING_INDEX(initial_date_str, ' ', 4);
	SET @fecha2 = TRIM(SUBSTRING_INDEX(@fecha1, ' ', -3));
	SET initial_date =  STR_TO_DATE(@fecha2, '%b %d %Y');
    
	SET @fecha1 = SUBSTRING_INDEX(final_date_str, ' ', 4);
	SET @fecha2 = TRIM(SUBSTRING_INDEX(@fecha1, ' ', -3));
	SET final_date =  STR_TO_DATE(@fecha2, '%b %d %Y');
*/
  
    delete from balance;
  
      FROM amortizacion A, inversion I where am_fecha_pago > (initial_date) 
       and am_fecha_pago <= final_date 
	   and inv_fecha_venta is null 
       and A.is_active = 1 
       and A.is_deleted = 0
       and I.is_deleted = 0
       and A.inv_id = I.id;
       
       

       select 'Bonos vencimiento próximo', sum(am_capital) as capital 
       from amortizacion A, inversion I 
       where am_fecha_pago > initial_date 
       and inv_fecha_venta is null 
       and A.is_active = 1 
       and A.is_deleted = 0
       and I.is_deleted = 0
       and A.inv_id = I.id
       and I.inv_tipo =4
       ;

       and I.is_deleted = 0
       and A.inv_id = I.id
       and I.inv_tipo =5
       ;

       and I.is_deleted = 0
       and A.inv_id = I.id
       and I.inv_tipo =3
       ;

       and I.is_deleted = 0
       and A.inv_id = I.id
       and I.inv_tipo = 91
       ;
       
       and I.is_deleted = 0
       and A.inv_id = I.id
       and I.inv_tipo = 73
       ;

       and I.is_deleted = 0
       and A.inv_id = I.id
       and I.inv_tipo = 75
       ;
       
  -- insert into balance select ov_description, ov_value from othervalue order by id;  
  select description as detalle, value as valor from balance
  union 
  select 'TOTAL' as detalle, sum(value) as valor from balance;
  
END$$

DROP PROCEDURE IF EXISTS `SP_BONDHIS_SELECT`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_BONDHIS_SELECT` (IN `_initialDate` DATE, IN `_finalDate` DATE)   BEGIN

SELECT 
	`bond_his`.`id` as id,
    `bond_his`.`FECHA` as fecha,
    `bond_his`.`DECRETO` as decreto,
    `bond_his`.`PRECIO_PORC` as precio_porc,
    `bond_his`.`RENDIMIENTO_PORC` as rendimiento,
    `bond_his`.`PLAZO_POR_VENCER` as dias_por_vencer,
     ROUND(plazo_por_vencer / 360, 2) AS anios_por_vencer,
    `bond_his`.`TASA_INTERES` as tasa_interes,
    `bond_his`.`VALOR_NOMINAL` as valor_nominal,
    `bond_his`.`VALOR_EFECTIVO` as valor_efectivo,
    `bond_his`.`FECHA_EMISION` as fecha_emision,
    `bond_his`.`FECHA_VENCIMIENTO` as fecha_vencimiento,
    `bond_his`.`PROCEDENCIA` as procedencia,
    `bond_his`.`TIPO` as tipo,
    `bond_his`.`TIPO_MERCADO_1` as tipo_mercado
FROM `bond_his`
WHERE (FECHA between _initialDate and _finalDate) or (FECHA=_initialDate)
ORDER BY rendimiento_porc desc;


END$$

DROP PROCEDURE IF EXISTS `SP_BOND_AMORTIZATION_CREATION`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_BOND_AMORTIZATION_CREATION` (IN `_inv_purchase_date` DATE, IN `_inv_expiration_date` DATE, IN `_inv_owner` VARCHAR(20), IN `_inv_enterprise` VARCHAR(100), IN `_inv_rate` DECIMAL(8,2), IN `_inv_return` DECIMAL(8,2), IN `_inv_principal` DECIMAL(8,2), IN `_inv_monthly_interest` DECIMAL(8,2), IN `_inv_previous_interest` DECIMAL(8,2), IN `_inv_first_date` DATE)   BEGIN
