DROP PROCEDURE IF EXISTS `SP_FACTURASHIS_SELECT`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_FACTURASHIS_SELECT` (IN `_initialDate` DATE, IN `_finalDate` DATE)   BEGIN

