DROP PROCEDURE IF EXISTS `SP_INVERTIDO_RENDIMIENTO`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_INVERTIDO_RENDIMIENTO` (IN `_type` VARCHAR(20))   BEGIN
	IF _type = 'BONO'  then
			SELECT SUM(pagado) AS invertido, rendimiento
			FROM bonos
			WHERE is_active = 1 AND is_deleted = 0 AND fechaVencimiento > NOW()
			GROUP BY rendimiento
			ORDER BY rendimiento DESC;
	END IF;
	IF _type = 'INVERSIONES' then
			SELECT SUM(A.am_capital) AS invertido, I.inv_rendimiento_nominal AS rendimiento
			FROM amortizacion A
			JOIN inversion I ON A.inv_id = I.id
			WHERE A.is_active = 1 AND A.is_deleted = 0 AND A.am_fecha_pago > NOW()
			  AND I.is_active = 1 AND I.is_deleted = 0 AND I.inv_fecha_vencimiento > NOW()
			  AND I.inv_tipo <> 4
			GROUP BY I.inv_rendimiento_nominal
			ORDER BY I.inv_rendimiento_nominal DESC;
	END IF;
END$$

DROP PROCEDURE IF EXISTS `SP_INVERTIDO_VENCIMIENTO`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_INVERTIDO_VENCIMIENTO` (IN `_type` VARCHAR(25))   BEGIN
    IF _type = 'BONO' THEN
        SELECT SUM(pagado) AS invertido, CAST(YEAR(fechaVencimiento) AS CHAR) AS anioVencimiento
        FROM bonos 
        WHERE is_active = 1 AND is_deleted = 0 AND fechaVencimiento > NOW()
        GROUP BY anioVencimiento 
        ORDER BY invertido DESC;
    END IF;

    IF _type = 'INVERSIONES' THEN
        SELECT SUM(A.am_capital) AS invertido, CAST(YEAR(A.am_fecha_pago) AS CHAR) AS anioVencimiento 
        FROM amortizacion A
        JOIN inversion I ON A.inv_id = I.id
        WHERE A.is_active = 1 AND A.is_deleted = 0 AND A.am_fecha_pago > NOW()
            AND I.is_active = 1 AND I.is_deleted = 0 AND I.inv_fecha_vencimiento > NOW()
            AND I.inv_tipo <> 4
        GROUP BY anioVencimiento 
        ORDER BY invertido DESC;
    END IF;
END$$

DROP PROCEDURE IF EXISTS `SP_INVESTMENT_BY_OWNER`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_INVESTMENT_BY_OWNER` ()   BEGIN

select 'BONO' as tipo, inv_propietario as propietario, sum(inv_capital_invertido) as capital  from inversion where inv_tipo = 4 and is_active = 1 group by inv_propietario

union

select 'OTRAS INVERSIONES', inv_propietario as propietario, sum(am_capital) as capital from amortizacion A, inversion I 
  where  
  am_fecha_pago > NOW()
  and inv_emisor not like '%BONOS%'
  and A.is_active = 1
  and A.is_deleted = 0
  and I.is_deleted = 0
  and A.inv_id = I.id
  group by inv_propietario;
  
  
END$$

