DROP PROCEDURE IF EXISTS `SP_INVESTMENT_BY_OWNER_TOTAL`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_INVESTMENT_BY_OWNER_TOTAL` (IN `TOTAL_STR` VARCHAR(10))   BEGIN

  CREATE TEMPORARY TABLE INVESTMENT_BY_OWNER_TEMP (
    tipo VARCHAR(45) NOT NULL,
    propietario VARCHAR(45) NOT NULL,
    capital DECIMAL(8,2) NOT NULL
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

  SELECT 'BONO' AS tipo, inv_propietario AS propietario, SUM(inv_capital_invertido) AS capital
  FROM inversion
  WHERE inv_tipo = 4 AND is_active = 1 AND inv_fecha_venta is null and inv_pagada = 0
  GROUP BY inv_propietario
  UNION
  SELECT 'OTRAS INVERSIONES' AS tipo, inv_propietario AS propietario, SUM(am_capital) AS capital
  FROM amortizacion A, inversion I
  WHERE am_fecha_pago > NOW() AND inv_emisor NOT LIKE '%BONOS%'
        and A.is_active = 1
       and A.is_deleted = 0
       and I.is_deleted = 0
       and A.inv_id = I.id
  GROUP BY inv_propietario;

  IF TOTAL_STR = 'NO' THEN
    SELECT tipo, propietario, capital FROM INVESTMENT_BY_OWNER_TEMP;
  ELSE
    SELECT tipo, propietario, capital FROM INVESTMENT_BY_OWNER_TEMP
    UNION
    SELECT '' AS tipo, 'TOTAL' AS propietario, SUM(capital) AS capital FROM INVESTMENT_BY_OWNER_TEMP;
  END IF;

  DROP TEMPORARY TABLE IF EXISTS INVESTMENT_BY_OWNER_TEMP;



END$$

DROP PROCEDURE IF EXISTS `SP_INVEST_INVERTIDO_RENDIMIENTO`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_INVEST_INVERTIDO_RENDIMIENTO` ()   SELECT sum(A.am_capital) invertido, I.inv_rendimiento_nominal as rendimiento
 FROM amortizacion A, inversion I
where A.is_active = 1 and A.is_deleted = 0 and A.am_fecha_pago > now()
      and I.is_active = 1 and I.is_deleted = 0 and I.inv_fecha_vencimiento > now()
      and A.inv_id = I.inv_id
      and inv_tipo <> 4
group by rendimiento order by rendimiento desc$$

DROP PROCEDURE IF EXISTS `SP_INVEST_INVERTIDO_VENCIMIENTO`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_INVEST_INVERTIDO_VENCIMIENTO` ()   SELECT sum(A.am_capital) invertido, year(A.am_fecha_pago) as anioVencimiento 
 FROM amortizacion A, inversion I
where A.is_active = 1 and A.is_deleted = 0 and A.am_fecha_pago > now()
      and I.is_active = 1 and I.is_deleted = 0 and I.inv_fecha_vencimiento > now()
      and A.inv_id = I.inv_id
      and inv_tipo <> 4
group by anioVencimiento order by anioVencimiento desc$$

