DROP PROCEDURE IF EXISTS `SP_RECUPERACION_ANUAL`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_RECUPERACION_ANUAL` (IN `_historico` INT)   BEGIN
   IF _historico = 0 THEN    -- SE BUSCA TODA LA INFORMACION PERO SOLO DE FECHAS FUTURAS
       SELECT CAST(YEAR(A.am_fecha_pago) AS CHAR) AS anio, 
              SUM(A.am_capital) AS capital, 
              SUM(A.am_interes) AS interes, 
              SUM(A.am_capital) + SUM(A.am_interes) AS total
       FROM amortizacion A, inversion I
       WHERE 
                   I.inv_fecha_venta IS NULL
		          and A.is_deleted = 0
                  and I.is_deleted = 0
                  and A.inv_id = I.id
           AND A.am_fecha_pago > CURDATE()
       GROUP BY anio 
       ORDER BY anio ASC;
   ELSE   -- SE NECESITA SOLO EL INTERES PERO DE TODOS LOS AÑOS PREVIOS
   
       SELECT CAST(YEAR(A.am_fecha_pago) AS CHAR) AS anio, 
              SUM(A.am_capital) AS capital, 
              SUM(A.am_interes) AS interes, 
              SUM(A.am_capital) + SUM(A.am_interes) AS total
       FROM amortizacion A, inversion I
       WHERE 
		   A.is_deleted = 0
           and I.is_deleted = 0
           and A.inv_id = I.id
           -- and A.is_active = 1
		   and (A.is_active = 1 OR  I.inv_fecha_venta IS NULL)
       GROUP BY anio 
       ORDER BY anio ASC;
       
       
       /*
       SELECT CAST(YEAR(A.am_fecha_pago) AS CHAR) AS anio, 
              SUM(A.am_capital) AS capital, 
              SUM(A.am_interes) AS interes, 
              SUM(A.am_capital) + SUM(A.am_interes) AS total
       FROM amortizacion A
       WHERE 
 		   A.is_deleted = 0
		   and A.is_active = 1
       GROUP BY anio 
       ORDER BY anio ASC;
      */
       
   END IF;

/*
       SELECT CAST(YEAR(A.am_fecha_pago) AS CHAR) AS anio, SUM(A.am_capital) AS capital, SUM(A.am_interes) AS interes, SUM(A.am_capital) + SUM(A.am_interes) as total
        FROM amortizacion A
        JOIN inversion I ON A.inv_id = I.id
        WHERE 
                -- A.is_active = 1 AND 
                A.is_deleted = 0 AND 
                -- A.am_fecha_pago >= curdate() AND 
                I.is_active = 1 AND 
                I.is_deleted = 0 
                -- AND 
               -- I.inv_fecha_vencimiento >= curdate()
--            AND I.inv_tipo <> 4
        GROUP BY anio 
        ORDER BY anio asc;
        
        */
        
END$$

DROP PROCEDURE IF EXISTS `SP_RESUMEN_QUINCENAL`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_RESUMEN_QUINCENAL` ()   BEGIN

SET @NUM_DIAS = 15;

truncate table rendimientos_his;

SELECT 
     5,
    `EMISOR`,
    AVG(`PRECIO_PORC`),
    AVG(`RENDIMIENTO`),
    AVG(`PLAZO_DIAS`),
    AVG(`INTERES`),
    SUM(VALOR_NOMINAL),
    SUM(VALOR_EFECTIVO),
    `EMISION`,
    `VENCIMIENTO`,
    `TIPO_MERCADO`,
    count(*) AS contador
FROM `obligaciones_his`
WHERE `FECHA` BETWEEN DATE_SUB(CURRENT_DATE, INTERVAL @NUM_DIAS DAY) AND CURRENT_DATE
GROUP BY `EMISOR`,`EMISION`, `VENCIMIENTO`, `TIPO_MERCADO`
ORDER BY RENDIMIENTO DESC;

SELECT 
     3,
    `EMISOR`,
    AVG(`PRECIO_PORC`),
    AVG(`RENDIMIENTO`),
    AVG(`PLAZO_DIAS`),
    AVG(`RENDIMIENTO`),
    SUM(VALOR_NOMINAL),
    SUM(VALOR_EFECTIVO),
    `EMISION`,
    `VENCIMIENTO`,
    `MERCADO`,
    count(*) AS contador
FROM `papeles_his`
WHERE `FECHA` BETWEEN DATE_SUB(CURRENT_DATE, INTERVAL @NUM_DIAS DAY) AND CURRENT_DATE
GROUP BY `EMISOR`,`EMISION`, `VENCIMIENTO`, `MERCADO`
ORDER BY RENDIMIENTO DESC;

SELECT 
     2,
    `EMISOR`,
    AVG(`PRECIO_PORC`),
    AVG(`RENDIMIENTO`),
    datediff(VENCIMIENTO, EMISION),
    AVG(`RENDIMIENTO`),
	SUM(VALOR_NOMINAL),
    SUM(VALOR_EFECTIVO),
    `EMISION`,
    `VENCIMIENTO`,
    '',
    count(*) AS contador
FROM `facturas_his`
WHERE `FECHA` BETWEEN DATE_SUB(CURRENT_DATE, INTERVAL @NUM_DIAS DAY) AND CURRENT_DATE
GROUP BY `EMISOR`,`EMISION`, `VENCIMIENTO`
ORDER BY RENDIMIENTO DESC;



SELECT 
