DROP PROCEDURE IF EXISTS `SP_SHARES_LAST_DATE`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_SHARES_LAST_DATE` ()   BEGIN

TRUNCATE TABLE shares_lastdate;
/*
CREATE TABLE `shares_lastdate` (
  `SHA_ISSUER_ID` int(11) NOT NULL,
  `SHA_ISSUER` varchar(100) DEFAULT NULL,
  `MAX_DATE` date DEFAULT NULL,
  `MAX_PRICE` decimal(8,2) DEFAULT NULL,
  `MIN_PRICE` decimal(8,2) DEFAULT NULL,
  `AVG_PRICE` decimal(8,2) DEFAULT NULL,
  PRIMARY KEY (`SHA_ISSUER_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

*/
CREATE TABLE `shares_lastdate_temp` (
  `SHA_ISSUER_ID` int(11) NOT NULL,
  `SHA_ISSUER` varchar(100) DEFAULT NULL,
  `MAX_DATE` date DEFAULT NULL,
  PRIMARY KEY (`SHA_ISSUER_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



# OBTIENE LA ÚLTIMA FECHA EN LA QUE SE TRANSACCIONÓ CON UNA EMPRESA    INICIO
SELECT SHA_ISSUER_ID, SHA_ISSUER, MAX(SHA_DATE) as max_date FROM shares 
WHERE SHA_CASH_VALUE > 0 and sha_date < '2026-12-31' GROUP BY SHA_ISSUER ORDER BY SHA_ISSUER;
# OBTIENE LA ÚLTIMA FECHA EN LA QUE SE TRANSACCIONÓ CON UNA EMPRESA    FIN

	SELECT A.SHA_ISSUER_ID ,
               A.SHA_ISSUER, 
               B.MAX_DATE,
               ROUND(SUM(A.SHA_CASH_VALUE) / SUM(A.SHA_NUMBER), 2) AS AVG_PRICE,
               ROUND(MIN(SHA_PRICE),2) AS MIN_PRICE, 
               ROUND(MAX(SHA_PRICE),2) AS MAX_PRICE
	from shares A, shares_lastdate_temp B 
	where A.SHA_DATE = B.MAX_DATE
	  AND A.SHA_ISSUER_ID = B.SHA_ISSUER_ID
	GROUP BY A.SHA_ISSUER_ID, A.SHA_DATE;
    

UPDATE shares A
SET A.sha_cash_value = (
    SELECT AVG_PRICE
    FROM shares_lastdate B
    WHERE A.SHA_DATE = '2026-12-31'
    AND A.SHA_ISSUER_ID = B.SHA_ISSUER_ID
)
WHERE A.SHA_DATE = '2026-12-31' ;



-- select * from shares_lastdate ORDER BY MAX_DATE DESC;

-- DROP TABLE shares_lastdate;
DROP TABLE shares_lastdate_temp;

        
    
END$$

DROP PROCEDURE IF EXISTS `SP_SHARES_SELECT`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_SHARES_SELECT` (IN `_initialDate` DATE, IN `_finalDate` DATE)   BEGIN


SELECT `shares`.`SHA_ID` as id,
    `shares`.`SHA_ISSUER_ID` as idemisor,
    `shares`.`SHA_DATE` as fecha,
    `shares`.`SHA_ISSUER` as emisor,
    `shares`.`SHA_TYPE` as tipo,
    `shares`.`SHA_NOMINAL_VALUE` as valornominal,
    `shares`.`SHA_PRICE` as precio,
    `shares`.`SHA_NUMBER` as cantidad,
    `shares`.`SHA_CASH_VALUE` as efectivo,
    `shares`.`SHA_PROVENANCE` as procedencia
FROM `shares`
WHERE  SHA_TYPE like '%ACCIONES%' and  
      ((SHA_DATE between _initialDate and _finalDate) or (SHA_DATE=_initialDate))
      

ORDER BY SHA_TYPE, SHA_ISSUER, SHA_PRICE desc;
END$$

DROP PROCEDURE IF EXISTS `SP_SHARES_SUMMARY`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_SHARES_SUMMARY` (IN `p_issuer` INT, IN `p_year` INT)   BEGIN
  IF p_issuer <> 0 AND p_year <> 0 THEN
    SELECT SHA_DATE AS fecha, 
           SHA_ISSUER AS emisor, 
           SUM(SHA_NUMBER) AS cantidad, 
           ROUND(SUM(SHA_CASH_VALUE),2) AS valor, 
           ROUND(SUM(SHA_CASH_VALUE) / SUM(SHA_NUMBER),2) AS precio, 
           COUNT(*) AS transacciones
    FROM shares
    WHERE SHA_ISSUER_ID = p_issuer and YEAR(SHA_DATE) = p_year and SHA_PRICE > 0
    GROUP BY SHA_DATE
    ORDER BY SHA_DATE;
  END IF;

  IF p_issuer <> 0 AND p_year = 0 THEN
    SELECT SHA_DATE AS fecha, 
           SHA_ISSUER AS emisor, 
           SUM(SHA_NUMBER) AS cantidad, 
           ROUND(SUM(SHA_CASH_VALUE),2) AS valor, 
           ROUND(SUM(SHA_CASH_VALUE) / SUM(SHA_NUMBER),2) AS precio, 
           COUNT(*) AS transacciones
    FROM shares
    WHERE SHA_ISSUER_ID = p_issuer and SHA_PRICE > 0
    GROUP BY SHA_DATE
    ORDER BY SHA_DATE;
  END IF;

  IF p_issuer = 0 THEN
    SELECT SHA_DATE AS fecha, 
           SHA_ISSUER AS emisor, 
           SUM(SHA_NUMBER) AS cantidad, 
           ROUND(SUM(SHA_CASH_VALUE),2) AS valor, 
           ROUND(SUM(SHA_CASH_VALUE) / SUM(SHA_NUMBER),2) AS precio, 
           COUNT(*) AS transacciones
    FROM shares
    WHERE SHA_PRICE > 0
    GROUP BY SHA_DATE
    ORDER BY SHA_DATE;
  END IF;
END$$

DROP PROCEDURE IF EXISTS `SP_SIMULACION_COMPRA_ACCIONES`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_SIMULACION_COMPRA_ACCIONES` (IN `_emisor_id` INT, IN `_precio_estimado` DECIMAL(8,2), IN `_capital` DECIMAL(8,2))   BEGIN


drop table `dividendo_temp`;

CREATE TABLE `dividendo_temp` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `divResolucion` date DEFAULT NULL,
  `divPrecio` double DEFAULT NULL,
  `divValorNominal` double DEFAULT NULL,
  `divCantidadAcciones` double DEFAULT NULL,
  `divEfectivo` double DEFAULT NULL,
  `divAcciones` double DEFAULT NULL,
  `divEfectivoRecibido` double DEFAULT NULL,
  `divAccionesRecibidas` double DEFAULT NULL,
  `divEfectivoPorAccRecibido` double DEFAULT NULL,
  `divEfectivoTotal` double DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;



-- SET _emisor_id = 35;
-- SET _capital = 1000;
SET @fechaActual = CURDATE();
SET @anioActual = YEAR(@fechaActual);
-- SET _precio_estimado = 3.3;

divResolucion, 
divPrecio, 
divValorNominal, 
divCantidadAcciones, 
divEfectivo, 
divAcciones, 
divEfectivoRecibido, 
divAccionesRecibidas,
divEfectivoPorAccRecibido,
DivEfectivototal
)
SELECT 
fecha_resolucion as divResolucion, 
ultimo_precio as divPrecio, 
valor_nominal as divValorNominal, 
_capital/ultimo_precio as divCantidadAcciones, 
dividendo_ef_por_accion as divEfectivo, 
aum_capital_capital_anterior as divAcciones, 
_capital/ultimo_precio*dividendo_ef_por_accion as divEfectivoRecibido, 
_capital/ultimo_precio*aum_capital_capital_anterior as divAccionesRecibidas, 
_capital/ultimo_precio*aum_capital_capital_anterior*ultimo_precio as divEfectivoPorAccRecibido,
_capital/ultimo_precio*dividendo_ef_por_accion + _capital/ultimo_precio*aum_capital_capital_anterior*ultimo_precio
FROM dividendos_his 
WHERE emisor_id = _emisor_id
AND YEAR(fecha_resolucion) > (@anioActual - 4);

-- delete from dividendo_temp where id = 2;

divResolucion, 
divPrecio, 
divValorNominal, 
divCantidadAcciones, 
divEfectivo, 
divAcciones, 
divEfectivoRecibido, 
divAccionesRecibidas,
divEfectivoPorAccRecibido,
DivEfectivototal
)
SELECT 
curdate(), 
_precio_estimado, 
avg(divValorNominal), 
_capital/_precio_estimado,  
avg(divEfectivo), 
avg(divAcciones), 
-- avg(divEfectivoRecibido), 
_capital/_precio_estimado*avg(divEfectivo) as divEfectivoRecibido, 
-- avg(divAccionesRecibidas),
_capital/_precio_estimado*avg(divAcciones) as divAccionesRecibidas,
-- avg(divEfectivoPorAccRecibido),
_capital/_precio_estimado*avg(divAcciones)*_precio_estimado as divEfectivoPorAccRecibido,
_capital/_precio_estimado*avg(divEfectivo) + _capital/_precio_estimado*avg(divAcciones)*_precio_estimado 
from dividendo_temp;


SELECT 
    `id` as id,
    `divResolucion` as resolucion,
    `divPrecio` as precio,
    `divValorNominal` as valorNominal,
    `divCantidadAcciones` as cantidadAcciones,
    `divEfectivo` as dividendoEfectivo,
    `divAcciones` as dividendoAcciones,
    `divEfectivoRecibido` as efectivoRecibido,
    `divAccionesRecibidas` as accionesRecibidas,
    `divEfectivoPorAccRecibido` as accionesEnEfectivo,
    `divEfectivoTotal` as efectivoTotal
FROM `dividendo_temp`;





END$$

