DROP PROCEDURE IF EXISTS `SP_VENTA_BONO`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_VENTA_BONO` (IN `_FechaCompra` DATE, IN `_FechaVencimiento` DATE, IN `_ValorNominalOriginal` DECIMAL(8,2), IN `_ValorVendido` DECIMAL(8,2))   BEGIN

SET @valorNominalRestante :=  _ValorNominalOriginal-_ValorVendido;

select id into @inv_id from inversion where inv_fecha_compra=_fechaCompra and inv_fecha_vencimiento=_fechaVencimiento and inv_valor_nominal = _valorNominalOriginal;


UPDATE bonos SET 
    interesMensual = interesMensual * (@valorNominalRestante / _valorNominalOriginal),
    interesPrimerMes = interesPrimerMes * (@valorNominalRestante / _valorNominalOriginal),
    valorNominal = valorNominal * (@valorNominalRestante / _valorNominalOriginal),
    valorSinComision = valorSinComision * (@valorNominalRestante / _valorNominalOriginal),
    valorConComision = valorConComision * (@valorNominalRestante / _valorNominalOriginal),
    Pagado = Pagado * (@valorNominalRestante / _valorNominalOriginal),
    InteresAcumuladoPrevio = InteresAcumuladoPrevio * (@valorNominalRestante / _valorNominalOriginal),
    ComisionCasa = ComisionCasa * (@valorNominalRestante / _valorNominalOriginal),
    ComisionBolsa = ComisionBolsa * (@valorNominalRestante / _valorNominalOriginal),
    totalComisiones = totalComisiones * (@valorNominalRestante / _valorNominalOriginal)
WHERE inv_id = @inv_id;

update inversion SET 
     inv_valor_nominal = inv_valor_nominal * (@valorNominalRestante / _valorNominalOriginal),
     inv_monto_a_negociar = inv_monto_a_negociar * (@valorNominalRestante / _valorNominalOriginal),
     inv_capital_invertido = inv_capital_invertido * (@valorNominalRestante / _valorNominalOriginal),
     inv_valor_efectivo = inv_valor_efectivo * (@valorNominalRestante / _valorNominalOriginal),
     inv_valor_interes = inv_valor_interes * (@valorNominalRestante / _valorNominalOriginal),
     inv_comision_bolsa = inv_comision_bolsa * (@valorNominalRestante / _valorNominalOriginal),
     inv_comision_operador = inv_comision_operador * (@valorNominalRestante / _valorNominalOriginal),
     inv_retencion = inv_retencion * (@valorNominalRestante / _valorNominalOriginal)
WHERE id = @inv_id;



-- select * from amortizacion where inv_id = 289 order by id desc;
UPDATE amortizacion SET
     am_interes = round(am_interes * (@valorNominalRestante / _valorNominalOriginal),2),
     am_capital = round(am_capital * (@valorNominalRestante / _valorNominalOriginal),2),
     am_descuento = round(am_descuento * (@valorNominalRestante / _valorNominalOriginal),2),
     am_int_parcial = round(am_int_parcial * (@valorNominalRestante / _valorNominalOriginal),2),
     am_total = round(am_total * (@valorNominalRestante / _valorNominalOriginal),2),
     am_retencion = round(am_retencion * (@valorNominalRestante / _valorNominalOriginal),2)
WHERE am_fecha_pago >= curdate()
and inv_id = @inv_id;

END$$

DROP PROCEDURE IF EXISTS `SP_VENTA_NOTAS_CREDITO`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_VENTA_NOTAS_CREDITO` (IN `FechaVenta` DATE)   BEGIN
		UPDATE amortizacion A set
		   A.is_active = 0
		where inv_id in 
		   (select id from inversion where inv_tipo = 91
			 and is_active = 1
			 and inv_liquidacion not in ('15167 - VRF40', '368604')
			 );
			 
			 
		UPDATE inversion 
		set is_active = 0, 
		   inv_fecha_venta = FechaVenta
		where is_active = 1
        and inv_tipo = 91
		and inv_liquidacion not in ('15167 - VRF40', '368604');

END$$

--
-- Funciones
--
DROP FUNCTION IF EXISTS `FormatDateString`$$
CREATE DEFINER=`root`@`localhost` FUNCTION `FormatDateString` (`date_str` VARCHAR(10)) RETURNS VARCHAR(10) CHARSET utf8mb4 COLLATE utf8mb4_general_ci  BEGIN
        DECLARE date_parts VARCHAR(3);
        DECLARE formatted_date VARCHAR(10);

        -- Dividir el string usando el carácter '/'
        SET date_parts = SUBSTRING_INDEX(date_str, '/', -1) + SUBSTRING_INDEX(SUBSTRING_INDEX(date_str, '/', 1), '/', -1);

        -- Reconstruir la fecha en el formato deseado
        SET formatted_date = STR_TO_DATE(date_parts, '%Y%m%d');

        RETURN formatted_date;

END$$

