  `inv_tasa_mensual_real` decimal(8,2) DEFAULT NULL,
  `inv_interes_primer_mes` decimal(8,2) DEFAULT NULL,
  `inv_fecha_primer_pago` date DEFAULT NULL,
  `inv_precio_comprado` double DEFAULT NULL,
  `inv_precio_neto_comprado` double DEFAULT NULL,
  `inv_valor_sin_comision` decimal(8,2) DEFAULT NULL,
