-- Volcado de datos para la tabla `inversion`
--


--
-- Disparadores `inversion`
--
DROP TRIGGER IF EXISTS `trg_after_insert_inversiones`;
DELIMITER $$
CREATE TRIGGER `trg_after_insert_inversiones` AFTER INSERT ON `inversion` FOR EACH ROW BEGIN

    IF NEW.inv_tipo = 4 THEN

            inv_id,
            fechaCompra,
            propietario,
            liquidacion,
            fechaEmision,
            fechaVencimiento,
            valorNominal,
            pagado,
            tasaMensual,
            rendimiento,
            interesMensual,
            comisionBolsa,
            comisionCasa,
            tasaMensualReal,
            interesPrimerMes,
            fechaPrimerPago,
            precioComprado,
            precioNetoComprado,
            valorSinComision,
            valorConComision,
            interesAcumuladoPrevio,
            totalComisiones,
            codigoSEB,
            codigoBCE,
            fechasPagosCapital
        )
        SELECT
            NEW.id,
            NEW.inv_fecha_compra,
            NEW.inv_propietario,
            NEW.inv_liquidacion,
            NEW.inv_fecha_emision,
            NEW.inv_fecha_vencimiento,
            NEW.inv_valor_nominal,
            NEW.inv_valor_con_interes,
            NEW.inv_tasa_interes,
            NEW.inv_rendimiento_nominal,
            NEW.inv_valor_interes,
            NEW.inv_comision_bolsa,
            NEW.inv_comision_operador,
            NEW.inv_tasa_mensual_real,
            NEW.inv_interes_primer_mes,
            NEW.inv_fecha_primer_pago,
            NEW.inv_precio_comprado,
            NEW.inv_precio_neto_comprado,
            NEW.inv_valor_sin_comision,
            NEW.inv_capital_invertido,
            NEW.inv_interes_acumulado_previo,
            NEW.inv_total_comisiones,
            NEW.inv_codigo_SEB,
            NEW.inv_codigo_BCE,
            NEW.inv_fechas_pagos_capital
        FROM DUAL
        WHERE NOT EXISTS (
            SELECT 1
            FROM bonos
            WHERE inv_id = NEW.id
        );

    END IF;

    IF NEW.inv_tipo = 91 THEN
		`inv_id`,
		`am_fecha_pago`,
		`am_interes`,
		`am_capital`,
		`am_descuento`,
		`am_int_parcial`,
		`am_total`,
		`am_retencion`
        )
        SELECT
            NEW.id,  -- inv_id
            '2034-12-31',  -- am_fecha_pago
            0,     -- am_interes       
            NEW.inv_capital_invertido, -- am_capital`
            0, -- am_descuento
            0, -- am_int_parcial   
            NEW.inv_capital_invertido, -- am_total
            0 -- am_retencion
        FROM DUAL
        WHERE NOT EXISTS (
            SELECT 1
            FROM amortizacion
            WHERE inv_id = NEW.id
        );
/*
        update inversion 
        set 
           inv_tasa_interes = 1,
           inv_rendimiento_nominal = 1,
           inv_tasa_mensual_real = 1,
           inv_valor_interes = 0,
           inv_instrumento = 'SRI 2034-12-31',
           id_instrumento = 222,
           inv_fecha_vencimiento = '2034-12-31',
		   inv_valor_con_interes = inv_capital_invertido,
		   inv_valor_sin_comision = inv_capital_invertido,
           inv_retencion=0,
           inv_monto_a_negociar = inv_valor_nominal,
           inv_interes_acumulado_previo=0
        where inv_tipo = 91;
*/
    END IF;


    IF NEW.inv_tipo = 73 THEN
		`inv_id`,
		`am_fecha_pago`,
		`am_interes`,
		`am_capital`,
		`am_descuento`,
		`am_int_parcial`,
		`am_total`,
		`am_retencion`
        )
        SELECT
            NEW.id,  -- inv_id
            NEW.inv_fecha_vencimiento,  -- am_fecha_pago
            NEW.inv_valor_interes,     -- am_interes       
            NEW.inv_capital_invertido, -- am_capital`
            0, -- am_descuento
            NEW.inv_valor_interes, -- am_int_parcial   
            NEW.inv_capital_invertido + NEW.inv_valor_interes, -- am_total
            0 -- am_retencion
        FROM DUAL
        WHERE NOT EXISTS (
            SELECT 1
            FROM amortizacion
            WHERE inv_id = NEW.id
        );

    END IF;


    IF NEW.inv_tipo = 3 THEN
		`inv_id`,
		`am_fecha_pago`,
		`am_interes`,
		`am_capital`,
		`am_descuento`,
		`am_int_parcial`,
		`am_total`,
		`am_retencion`
        )
        SELECT
            NEW.id,  -- inv_id
            NEW.inv_fecha_vencimiento,  -- am_fecha_pago
            NEW.inv_valor_nominal - NEW.inv_capital_invertido,     -- am_interes       
            NEW.inv_capital_invertido, -- am_capital`
            0, -- am_descuento
            NEW.inv_valor_nominal - NEW.inv_capital_invertido, -- am_int_parcial   
            NEW.inv_capital_invertido, -- am_total
            0 -- am_retencion
        FROM DUAL
        WHERE NOT EXISTS (
            SELECT 1
            FROM amortizacion
            WHERE inv_id = NEW.id
        );

    END IF;


END
$$
DELIMITER ;

